targets.expr:
label_replace(
  (
100 * (
  max by (node, disk) (longhorn_disk_usage_bytes)
  / max by (node, disk) (longhorn_disk_capacity_bytes > 0)
)
  ),
  "storage_column", "Used", "", ".*"
)

label_replace(
  (
(max by (volume, pvc_namespace, pvc) (longhorn_volume_capacity_bytes{namespace="longhorn"}) * 0 + 1) * on (volume) group_left () (count by (volume) (
  max by (volume, backup) (longhorn_backup_state{namespace="longhorn"}) == 3
))
or on (volume) (max by (volume, pvc_namespace, pvc) (longhorn_volume_capacity_bytes{namespace="longhorn"}) * 0)
  ),
  "backup_column", "Completed Backups", "", ".*"
)
